document.addEventListener("DOMContentLoaded", () => {

    const year = new Date().getFullYear();

    document.querySelectorAll(".clt-footer-right").forEach(el => {
        el.textContent = `© ${el.textContent} - ${year}`;
    });

    document.querySelectorAll("[clt]").forEach((element, index) => {

        const value = element.getAttribute("clt");

        if (element.tagName === "INPUT" || element.tagName === "TEXTAREA") {

            const wrapper = document.createElement("div");
            wrapper.className = "clt-input-group";

            const inputWrapper = document.createElement("div");
            inputWrapper.className = "clt-input-wrapper";

            const id = element.id || `clt-input-${index}`;
            element.id = id;

            element.classList.add("clt-input");

            if (element.tagName === "TEXTAREA") {
                element.classList.add("clt-textarea");

                const autoResize = () => {
                    element.style.height = "auto";
                    element.style.height = element.scrollHeight + "px";
                };

                element.addEventListener("input", autoResize);
                requestAnimationFrame(autoResize);
            }

            if (!element.hasAttribute("placeholder")) {
                element.placeholder = " ";
            }

            const label = document.createElement("label");
            label.className = "clt-label";
            label.htmlFor = id;
            label.textContent = value;

            element.removeAttribute("clt");

            const parent = element.parentNode;

            if (parent) {
                parent.insertBefore(wrapper, element);
                wrapper.appendChild(inputWrapper);
                inputWrapper.appendChild(element);
                inputWrapper.appendChild(label);
            }

            if (element.hasAttribute("reveal")) {
                element.type = 'password';
                const revealLabel = document.createElement("label");
                revealLabel.className = "clt-reveal";

                const revealCheckbox = document.createElement("input");
                revealCheckbox.type = "checkbox";

                const revealText = document.createElement("span");
                revealText.textContent = "Mostrar";

                revealCheckbox.addEventListener("change", () => {
                    element.type = revealCheckbox.checked ? "text" : "password";
                });

                element.removeAttribute("reveal");

                revealLabel.appendChild(revealCheckbox);
                revealLabel.appendChild(revealText);
                wrapper.appendChild(revealLabel);
            }
        }

        if (element.tagName === "BUTTON") {

            const state = value.toLowerCase();

            if (state === "on") {
                element.classList.add("clt-active-button");
                element.disabled = false;
            }

            if (state === "off") {
                element.classList.add("clt-deactive-button");
                element.disabled = true;
            }

            if (state === "loading") {
                element.classList.add("clt-loading");
                element.disabled = true;

                if (!element.querySelector(".clt-spinner")) {
                    const spinner = document.createElement("span");
                    spinner.className = "clt-spinner";
                    spinner.textContent = "↻";
                    element.prepend(spinner);
                }
            }

            element.removeAttribute("clt");
        }
    });

    document.querySelectorAll(".clt-cookies").forEach(element => {

    if (localStorage.getItem("clt-cookies-accepted") === "true" || localStorage.getItem("clt-cookies-accepted") === "false") {

        element.style.display = "none";

    } else {

        element.innerHTML = `
            <span class="clt-cookies-text">
                🍪 Este site utiliza cookies para garantir a melhor experiência de navegação,
                analisar o tráfego e personalizar conteúdos. Ao clicar em 'Aceitar todos',
                você concorda com o uso de cookies. Você pode gerenciar suas preferências
                na Política de Privacidade.
            </span>

            <button class="clt-cookies-button" onclick="cltCookies('true')">
                Aceitar todos
            </button>

            <button class="clt-cookies-button-not" onclick="cltCookies('false')">
                Rejeitar todos
            </button>
        `;

        element.classList.add("clt-cookies-animation-in");
    }
});

    document.querySelectorAll(".clt-progress").forEach(element => {

    element.innerHTML = `
        <div class="clt-progress-thumb"></div>
    `;

    const thumb = element.querySelector(".clt-progress-thumb");

    const updateProgress = () => {

        const scrollTop = window.scrollY;

        const height =
            document.documentElement.scrollHeight -
            document.documentElement.clientHeight;

        const percentage = height > 0
            ? (scrollTop / height) * 100
            : 0;

        thumb.style.width = percentage + "%";
    };

    window.addEventListener("scroll", updateProgress);

    updateProgress();
});

    document.querySelectorAll("clt-alert").forEach(alert => {

        const div = document.createElement("div");
        div.className = "clt-alert";

        const type = (alert.getAttribute("type") || "").toLowerCase();

        let icon = "ℹ";

        if (type === "warn") {
            div.classList.add("clt-alert-warn");
            icon = "⚠";
        }

        if (type === "alert") {
            div.classList.add("clt-alert-alert");
            icon = "✖";
        }

        const iconSpan = document.createElement("span");
        iconSpan.className = "clt-alert-icon";
        iconSpan.textContent = icon;

        const textSpan = document.createElement("span");
        textSpan.className = "clt-alert-text";
        textSpan.innerHTML = alert.innerHTML;

        div.appendChild(iconSpan);
        div.appendChild(textSpan);

        alert.replaceWith(div);
    });

    document.querySelectorAll("[clt-copy]").forEach(button => {
        button.addEventListener("click", async () => {

            const target = document.getElementById(button.getAttribute("clt-copy"));

            if (!target) return;

            const original = button.textContent;

            await navigator.clipboard.writeText(target.textContent);

            button.textContent = "Copied!";
            button.classList.add("clt-active-button");

            setTimeout(() => {
                button.textContent = original;
                button.classList.remove("clt-active-button");
            }, 1200);
        });
    });

    document.querySelectorAll("[clt-download]").forEach(button => {
        button.addEventListener("click", () => {

            const file = button.getAttribute("clt-download");
            const name = button.getAttribute("download-name") || file.split("/").pop();

            const link = document.createElement("a");
            link.href = file;
            link.download = name;
            document.body.appendChild(link);
            link.click();
            link.remove();
        });
    });

    let container = document.querySelector(".clt-toast-container");

    if (!container) {
        container = document.createElement("div");
        container.className = "clt-toast-container";
        document.body.appendChild(container);
    }

    function createToast(el, index) {

        const type = el.getAttribute("clt-toast") || "info";
        const show = el.getAttribute("show");
        const when = el.getAttribute("when");

        const div = document.createElement("div");
        div.classList.add("clt-toast");

        if (type === "info") div.classList.add("clt-toast-info");
        if (type === "alert") div.classList.add("clt-toast-alert");

        const icon = document.createElement("span");
        icon.className = "clt-alert-icon";
        icon.textContent = type === "alert" ? "⚠" : "ℹ";

        const text = document.createElement("span");
        text.className = "clt-alert-text";
        text.innerHTML = el.innerHTML;

        div.appendChild(icon);
        div.appendChild(text);

        el.remove();

        let fired = false;

        const run = () => {
            if (fired) return;
            fired = true;

            container.appendChild(div);

            requestAnimationFrame(() => {
                div.classList.add("show");
            });

            const removeToast = () => {
                div.classList.remove("show");
                div.classList.add("hide");

                setTimeout(() => div.remove(), 300);
            };

            setTimeout(removeToast, 3000 + index * 200);
        };

        if (show) {
            setTimeout(run, parseFloat(show) * 1000);
        } else {
            run();
        }

        if (when) {
            const eventName = `clt:${when}`;

            const handler = () => {
                run();
                window.removeEventListener(eventName, handler);
            };

            window.addEventListener(eventName, handler);
        }
    }

    window.cltToast = (message, type = "info") => {
        const el = document.createElement("div");
        el.setAttribute("clt-toast", type);
        el.textContent = message;
        createToast(el, document.querySelectorAll(".clt-toast").length);
    };

    document.querySelectorAll("[clt-toast]").forEach((el, index) => {
        createToast(el, index);
    });
});

function cltCookies(accept) {
    const div = document.querySelector(".clt-cookies");

    div.style.bottom = "0px";

    div.classList.remove("clt-cookies-animation-in");
    div.classList.add("clt-cookies-animation-out");

    if (accept === 'true') {
        localStorage.setItem("clt-cookies-accepted", "true");
    }
    else {
       localStorage.setItem("clt-cookies-accepted", "false"); 
    }

    setTimeout(() => {
        div.style.display = "none";
    }, 1000);
}
